package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat#isLenient
 */
public class StdDateFormat_isLenient_TriageGen2Test {







    @Test
    public void testIsLenientAfterClone() {
        StdDateFormat df = new StdDateFormat();
        df.setLenient(true);
        StdDateFormat cloned = df.clone();
        assertTrue("Cloned instance should maintain the lenient setting", cloned.isLenient());

        cloned.setLenient(false);
        assertFalse("Cloned instance should be able to change setting independently", cloned.isLenient());
        assertTrue("Original instance should remain unchanged", df.isLenient());
    }
}
